// testKeyList builds a master key list from generated bytes, never from a literal key.
func testKeyList(version int) string {
	raw := make([]byte, 32)
	for i := range raw {
		raw[i] = byte(0x30 + i)
	}

	return string(rune('0'+version)) + ":" + base64.StdEncoding.EncodeToString(raw)
}

func newTestHandler(t *testing.T, cfg *config.Config, store confighandler.Store) confighandler.Handler {
	t.Helper()

	h, err := New(cfg, store)
	if err != nil {
		t.Fatalf("Wrong match. expect: ok, got: %v", err)
	}

	return h
}

func setSecret(t *testing.T, h confighandler.Handler, key, value string) {
	t.Helper()

	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), key, value); err != nil {
		t.Fatalf("Wrong match. expect: ok, got: %v", err)
	}
}

// With no stored row the environment variable of the key is the value, for both keys. The
// suppliers read it at the time of use (the variable is set after the handler exists).
func Test_Supplier_noRowUsesTheEnvironment(t *testing.T) {
	tests := []struct {
		name string
		key  string
		env  string
	}{
		{name: "api key", key: configkeys.KeyPaddleAPIKey, env: "PADDLE_API_KEY"},
		{name: "webhook secret", key: configkeys.KeyPaddleWebhookSecretKey, env: "PADDLE_WEBHOOK_SECRET_KEY"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// the handler is created from New: the lookup is os.LookupEnv (a nil lookup would
			// make this test fail, and so would a lookup that is captured at creation)
			h := newTestHandler(t, &config.Config{}, storetest.NewMemory())
			supplier := Supplier(h, tt.key)

			t.Setenv(tt.env, "")
			if v, err := supplier(context.Background()); err != nil || v != "" {
				t.Errorf("Wrong match. expect: not configured, got: %q %v", v, err)
			}

			t.Setenv(tt.env, "env-value-"+tt.name)
			if v, err := supplier(context.Background()); err != nil || v != "env-value-"+tt.name {
				t.Errorf("Wrong match. expect: the environment value, got: %q %v", v, err)
			}

			_, res, err := h.Secret(context.Background(), tt.key)
			if err != nil || res.Source != confighandler.SourceEnv || res.EnvShadowed {
				t.Errorf("Wrong match. expect: source env, got: %+v %v", res, err)
			}
		})
	}
}

// With a stored row the stored value wins and the environment is shadowed, for both keys.
func Test_Supplier_rowWinsOverTheEnvironment(t *testing.T) {
	tests := []struct {
		name string
		key  string
		env  string
	}{
		{name: "api key", key: configkeys.KeyPaddleAPIKey, env: "PADDLE_API_KEY"},
		{name: "webhook secret", key: configkeys.KeyPaddleWebhookSecretKey, env: "PADDLE_WEBHOOK_SECRET_KEY"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Setenv(tt.env, "env-value")
			h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, storetest.NewMemory())
			setSecret(t, h, tt.key, "stored-value")

			if v, err := Supplier(h, tt.key)(context.Background()); err != nil || v != "stored-value" {
				t.Errorf("Wrong match. expect: the stored value, got: %q %v", v, err)
			}
			_, res, _ := h.Secret(context.Background(), tt.key)
			if res.Source != confighandler.SourceDB || !res.EnvShadowed {
				t.Errorf("Wrong match. expect: source db and env shadowed, got: %+v", res)
			}
		})
	}
}

// New hands os.LookupEnv to the library. A handler that is built with another lookup does not see
// the process environment, which tells New (os.LookupEnv) from a nil lookup.
func Test_New_usesTheProcessEnvironment(t *testing.T) {
	t.Setenv("PADDLE_API_KEY", "process-env-value")

	viaNew := Supplier(newTestHandler(t, &config.Config{}, storetest.NewMemory()), configkeys.KeyPaddleAPIKey)
	if v, err := viaNew(context.Background()); err != nil || v != "process-env-value" {
		t.Errorf("Wrong match. expect: the value of the process environment, got: %q %v", v, err)
	}

	nilEnv, err := newWithEnv(&config.Config{}, storetest.NewMemory(), nil)
	if err != nil {
		t.Fatalf("Wrong match. expect: ok, got: %v", err)
	}
	if v, errGet := Supplier(nilEnv, configkeys.KeyPaddleAPIKey)(context.Background()); errGet != nil || v != "" {
		t.Errorf("Wrong match. expect: nothing from a nil lookup, got: %q %v", v, errGet)
	}

	fake := func(name string) (string, bool) {
		if name == "PADDLE_API_KEY" {
			return "fake-value", true
		}
		return "", false
	}
	injected, err := newWithEnv(&config.Config{}, storetest.NewMemory(), fake)
	if err != nil {
		t.Fatalf("Wrong match. expect: ok, got: %v", err)
	}
	if v, errGet := Supplier(injected, configkeys.KeyPaddleAPIKey)(context.Background()); errGet != nil || v != "fake-value" {
		t.Errorf("Wrong match. expect: the injected value, got: %q %v", v, errGet)
	}
}

// A change of the stored value or of the variable is used by the next call of the same supplier.
func Test_Supplier_resolvedAtRequestTime(t *testing.T) {
	t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", "env-1")
	store := storetest.NewMemory()
	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
	supplier := Supplier(h, configkeys.KeyPaddleWebhookSecretKey)
	ctx := context.Background()

	steps := []struct {
		name   string
		act    func()
		expect string
	}{
		{"environment", func() {}, "env-1"},
		{"environment changed", func() { t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", "env-2") }, "env-2"},
		{"stored", func() { setSecret(t, h, configkeys.KeyPaddleWebhookSecretKey, "db-1") }, "db-1"},
		{"stored again", func() { setSecret(t, h, configkeys.KeyPaddleWebhookSecretKey, "db-2") }, "db-2"},
		{"cleared", func() {
			if _, err := h.Clear(ctx, uuid.Must(uuid.NewV4()), configkeys.KeyPaddleWebhookSecretKey); err != nil {
				t.Fatalf("Wrong match. expect: ok, got: %v", err)
			}
		}, "env-2"},
	}
	for _, step := range steps {
		step.act()
		if v, err := supplier(ctx); err != nil || v != step.expect {
			t.Errorf("Wrong match. %s: expect: %q, got: %q %v", step.name, step.expect, v, err)
		}
	}
}

// A read or decrypt error is an error and never falls through to the environment variable.
func Test_Supplier_readErrorsDoNotFallBack(t *testing.T) {
	t.Setenv("PADDLE_API_KEY", "env-api")
	t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", "env-webhook")

	check := func(t *testing.T, h confighandler.Handler) {
		t.Helper()

		for _, key := range []string{configkeys.KeyPaddleAPIKey, configkeys.KeyPaddleWebhookSecretKey} {
			v, err := Supplier(h, key)(context.Background())
			if !errors.Is(err, paddlehandler.ErrKeyUnavailable) || v != "" {
				t.Errorf("Wrong match. %s: expect: ErrKeyUnavailable and no value, got: %q %v", key, v, err)
			}
		}
	}

	t.Run("read error", func(t *testing.T) {
		store := storetest.NewMemory()
		store.GetErr = errors.New("database is down")
		check(t, newTestHandler(t, &config.Config{}, store))
	})

	t.Run("no master key for a stored row", func(t *testing.T) {
		store := storetest.NewMemory()
		writer := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
		setSecret(t, writer, configkeys.KeyPaddleAPIKey, "db-a")
		setSecret(t, writer, configkeys.KeyPaddleWebhookSecretKey, "db-w")

		check(t, newTestHandler(t, &config.Config{}, store))
	})

	t.Run("wrong master key", func(t *testing.T) {
		store := storetest.NewMemory()
		writer := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
		setSecret(t, writer, configkeys.KeyPaddleAPIKey, "db-a")
		setSecret(t, writer, configkeys.KeyPaddleWebhookSecretKey, "db-w")

		other := make([]byte, 32)
		for i := range other {
			other[i] = byte(0x70 + i)
		}
		wrong := "1:" + base64.StdEncoding.EncodeToString(other)
		check(t, newTestHandler(t, &config.Config{ConfigEncryptionKeys: wrong}, store))
	})

	t.Run("tampered ciphertext", func(t *testing.T) {
		store := storetest.NewMemory()
		writer := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
		setSecret(t, writer, configkeys.KeyPaddleAPIKey, "db-a")
		setSecret(t, writer, configkeys.KeyPaddleWebhookSecretKey, "db-w")

		check(t, newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, tamperingStore{Store: store}))
	})

	t.Run("one key fails", func(t *testing.T) {
		store := storetest.NewMemory()
		store.GetErrByKey = map[string]error{configkeys.KeyPaddleWebhookSecretKey: errors.New("read failed")}
		h := newTestHandler(t, &config.Config{}, store)

		if v, err := Supplier(h, configkeys.KeyPaddleAPIKey)(context.Background()); err != nil || v != "env-api" {
			t.Errorf("Wrong match. expect: the other key is read, got: %q %v", v, err)
		}
		if v, err := Supplier(h, configkeys.KeyPaddleWebhookSecretKey)(context.Background()); !errors.Is(err, paddlehandler.ErrKeyUnavailable) || v != "" {
			t.Errorf("Wrong match. expect: ErrKeyUnavailable, got: %q %v", v, err)
		}
	})
}

// tamperingStore flips a bit of the ciphertext of every row that it reads.
type tamperingStore struct {
	confighandler.Store
}

func (s tamperingStore) Get(ctx context.Context, key string) (*confighandler.Row, error) {
	row, err := s.Store.Get(ctx, key)
	if err != nil {
		return nil, err
	}

	tampered := *row
	tampered.SecretCiphertext = append([]byte(nil), row.SecretCiphertext...)
	tampered.SecretCiphertext[len(tampered.SecretCiphertext)-1] ^= 0xff

	return &tampered, nil
}

type blockingStore struct {
	confighandler.Store
}

func (blockingStore) Get(ctx context.Context, key string) (*confighandler.Row, error) {
	<-ctx.Done()
	return nil, ctx.Err()
}

// A read that does not return is cut at the bound, and the cause is visible.
func Test_Supplier_bounds(t *testing.T) {
	h := newTestHandler(t, &config.Config{}, blockingStore{Store: storetest.NewMemory()})
	supplier := Supplier(h, configkeys.KeyPaddleWebhookSecretKey)

	started := time.Now()
	_, err := supplier(context.Background())
	if !errors.Is(err, paddlehandler.ErrKeyUnavailable) || !errors.Is(err, context.DeadlineExceeded) {
		t.Errorf("Wrong match. expect: ErrKeyUnavailable wrapping the deadline, got: %v", err)
	}
	if took := time.Since(started); took < readTimeout-100*time.Millisecond || took > readTimeout+time.Second {
		t.Errorf("Wrong match. expect: about %v, got: %v", readTimeout, took)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if _, err := supplier(ctx); !errors.Is(err, paddlehandler.ErrKeyUnavailable) {
		t.Errorf("Wrong match. expect: ErrKeyUnavailable, got: %v", err)
	}
}

// No key value reaches an error text or a log line, from the environment or from the database.
func Test_Supplier_holdsNoValueInErrorsOrLogs(t *testing.T) {
	const secret = "synthetic-credential-text"
	t.Setenv("PADDLE_API_KEY", secret)
	t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", secret)

	logs := logtest.New(t)

	store := storetest.NewMemory()
	store.GetErr = errors.New("database is down")
	_, err := Supplier(newTestHandler(t, &config.Config{}, store), configkeys.KeyPaddleAPIKey)(context.Background())
	if err == nil || strings.Contains(err.Error(), secret) {
		t.Errorf("Wrong match. the key reached the error: %v", err)
	}

	ok := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, storetest.NewMemory())
	setSecret(t, ok, configkeys.KeyPaddleAPIKey, "stored-credential-text")
	_, _ = Supplier(ok, configkeys.KeyPaddleAPIKey)(context.Background())
	LogSources(context.Background(), ok)

	logs.AssertAbsent(t, secret, "stored-credential-text")
}

// A bad master key list never stops the service and is never printed.
func Test_New_badMasterKeyIsLoggedWithoutTheText(t *testing.T) {
	var buf bytes.Buffer
	prev := logrus.StandardLogger().Out
	logrus.SetOutput(&buf)
	defer logrus.SetOutput(prev)

	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: "7:unlikely-to-appear-in-logs"}, storetest.NewMemory())

	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyPaddleAPIKey, "x"); !errors.Is(err, confighandler.ErrKeyNotConfigured) {
		t.Errorf("Wrong match. expect: key not configured, got: %v", err)
	}
	if !strings.Contains(buf.String(), config.EnvConfigEncryptionKeys) {
		t.Errorf("Wrong match. expect: the problem to be logged, got: %q", buf.String())
	}
	if strings.Contains(buf.String(), "unlikely-to-appear-in-logs") {
		t.Errorf("Wrong match. the key list text was logged")
	}
}

// Without a master key list the handler is created without an error, the environment still serves
// the keys, and an empty list is not reported as an error.
func Test_New_noMasterKey(t *testing.T) {
	t.Setenv("PADDLE_API_KEY", "env-api")
	logs := logtest.New(t)

	h := newTestHandler(t, &config.Config{}, storetest.NewMemory())

	if v, err := Supplier(h, configkeys.KeyPaddleAPIKey)(context.Background()); err != nil || v != "env-api" {
		t.Errorf("Wrong match. expect: the environment value, got: %q %v", v, err)
	}
	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyPaddleWebhookSecretKey, "x"); !errors.Is(err, confighandler.ErrKeyNotConfigured) {
		t.Errorf("Wrong match. expect: key not configured, got: %v", err)
	}
	if strings.Contains(logs.Dump(), config.EnvConfigEncryptionKeys) {
		t.Errorf("Wrong match. an empty master key list must not be reported: %s", logs.Dump())
	}
}

func Test_PaddleKeys(t *testing.T) {
	t.Setenv("PADDLE_API_KEY", "env-api")
	t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", "env-webhook")

	apiKey, webhookSecret := PaddleKeys(newTestHandler(t, &config.Config{}, storetest.NewMemory()))
	if v, err := apiKey(context.Background()); err != nil || v != "env-api" {
		t.Errorf("Wrong match. expect: env-api, got: %q %v", v, err)
	}
	if v, err := webhookSecret(context.Background()); err != nil || v != "env-webhook" {
		t.Errorf("Wrong match. expect: env-webhook, got: %q %v", v, err)
	}
}

// LogSources: the webhook secret that is not configured is a warning (the signature is not
// checked), the API key that is not configured is an info line, a value from the environment or the
// database is an info line, an unusable stored value is an error, and no line holds a value.
func Test_LogSources(t *testing.T) {
	t.Run("nothing configured", func(t *testing.T) {
		t.Setenv("PADDLE_API_KEY", "")
		t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", "")
		logs := logtest.New(t)
		LogSources(context.Background(), newTestHandler(t, &config.Config{}, storetest.NewMemory()))

		levels := map[any]logrus.Level{}
		for _, e := range logs.Entries() {
			levels[e.Data["key"]] = e.Level
		}
		if levels[configkeys.KeyPaddleWebhookSecretKey] != logrus.WarnLevel {
			t.Errorf("Wrong match. expect: a warning for the webhook secret, got: %v", levels)
		}
		if levels[configkeys.KeyPaddleAPIKey] != logrus.InfoLevel {
			t.Errorf("Wrong match. expect: an info line for the API key, got: %v", levels)
		}
		if logs.HasLevel(logrus.ErrorLevel) {
			t.Errorf("Wrong match. expect: no error, got: %s", logs.Dump())
		}
	})

	t.Run("environment and database are info", func(t *testing.T) {
		t.Setenv("PADDLE_API_KEY", "env-api-text")
		t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", "")
		store := storetest.NewMemory()
		h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
		setSecret(t, h, configkeys.KeyPaddleWebhookSecretKey, "stored-secret-text")

		logs := logtest.New(t)
		LogSources(context.Background(), h)

		sources := map[any]any{}
		for _, e := range logs.Entries() {
			sources[e.Data["key"]] = e.Data["source"]
			if e.Level != logrus.InfoLevel {
				t.Errorf("Wrong match. expect: info lines only, got: %v %s", e.Level, e.Message)
			}
		}
		if sources[configkeys.KeyPaddleAPIKey] != confighandler.SourceEnv || sources[configkeys.KeyPaddleWebhookSecretKey] != confighandler.SourceDB {
			t.Errorf("Wrong match. got: %v", sources)
		}
		logs.AssertAbsent(t, "env-api-text", "stored-secret-text")
	})

	t.Run("undecryptable is an error", func(t *testing.T) {
		t.Setenv("PADDLE_WEBHOOK_SECRET_KEY", "env-webhook-text")
		store := storetest.NewMemory()
		writer := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
		setSecret(t, writer, configkeys.KeyPaddleWebhookSecretKey, "stored-secret-text")

		logs := logtest.New(t)
		LogSources(context.Background(), newTestHandler(t, &config.Config{}, store))

		out := logs.Dump()
		if !strings.Contains(out, "The stored config value can not be used. key: paddle.webhook_secret_key") || !logs.HasLevel(logrus.ErrorLevel) {
			t.Errorf("Wrong match. expect: an error for the unusable stored value, got: %s", out)
		}
		logs.AssertAbsent(t, "stored-secret-text", "env-webhook-text")
	})
}

func Test_LogSources_readError(t *testing.T) {
	store := storetest.NewMemory()
	store.ListErr = errors.New("database is down")

	logs := logtest.New(t)
	LogSources(context.Background(), newTestHandler(t, &config.Config{}, store))

	if !logs.HasLevel(logrus.WarnLevel) {
		t.Errorf("Wrong match. expect: a warning, got: %s", logs.Dump())
	}
	if logs.HasLevel(logrus.ErrorLevel) || logs.HasLevel(logrus.FatalLevel) || logs.HasLevel(logrus.PanicLevel) {
		t.Errorf("Wrong match. expect: a warning only, got: %s", logs.Dump())
	}
}
